async function (m, { conn }) {
  if (m.id && !m.isBaileys) {
    msgCache.set(m.id, m)
    if (msgCache.size > 3000) msgCache.delete(msgCache.keys().next().value)
  }

  if (m.message?.protocolMessage?.type === 0 || m.message?.protocolMessage?.type === 14) {
    let chat = global.db.data.chats[m.chat] || {}
    if (!chat.antidelete) return !0

    const key = m.message.protocolMessage.key
    const originalMsg = msgCache.get(key.id) || (typeof conn.loadMessage === "function" ? await conn.loadMessage(key.remoteJid, key.id) : null)

    if (originalMsg && !key.fromMe) {
      const textContent = originalMsg.text || originalMsg.caption || ""
      const isLink = /(chat\.whatsapp\.com|wa\.me)/i.test(textContent)

      if (!isLink) {
        const realSender = await resolveLidToPn(key.participant || key.remoteJid, conn) || key.participant || key.remoteJid
        const displayName = await getDisplayName(realSender, conn)
        let msgType = "Desconocido"

        if (originalMsg.message) {
          const rawType = Object.keys(originalMsg.message).filter(v => v !== "messageContextInfo" && v !== "senderKeyDistributionMessage")[0]
          if (rawType) {
            msgType = rawType
              .replace("Message", "")
              .replace("conversation", "Texto")
              .replace("extendedText", "Texto")
              .replace("image", "Imagen")
              .replace("video", "Video")
              .replace("audio", "Audio")
              .replace("document", "Documento")
              .replace("sticker", "Sticker")
              .replace("buttons", "Botones")
              .replace("template", "Plantilla")
              .replace("interactive", "Interactivo")
          }
        }

        const antideleteText = `み❑     *M E N S A J E  -  B O R R A D O*    ✿

> *₊·や✿ね Usuario* » @${displayName}
> *₊·や✿ね Tipo* » ${msgType.charAt(0).toUpperCase() + msgType.slice(1)}
> *₊·や✿ね Chat* » ${m.isGroup ? "Grupo" : "Privado"}`

        await conn.sendMessage(key.remoteJid, {
          text: antideleteText,
          mentions: [realSender]
        }, { quoted: metaai }).catch(() => {})

        await conn.sendMessage(key.remoteJid, {
          forward: originalMsg
        }, { quoted: metaai }).catch(() => {})
      }
    }
  }

  return !0
}

