  const setting = data?.settings?.[botJid] || data?.settings?.[conn.user?.id] || {}
  if (!(cfg.enabled === true || setting.ai === true) || data?.chats?.[m.chat]?.aichat === false || data?.chats?.[m.chat]?.isBanned === true) return true
