    const prefixes = Array.isArray(prefix) ? prefix : typeof prefix === 'string' ? [prefix] : ['.', '!', '/', '#']
    if (prefixes.some(p => typeof p === 'string' && p.length && text.startsWith(p))) return true
  }
  const media = pickMedia(m) || pickMedia(m.quoted)
  if (!text && !media) return true
  if (!media && Array.from(text).length < 2) return true
  if (cfg.mentionOnly && (m.isGroup || m.chat.endsWith('@g.us'))) {
    const botIds = [conn.user?.jid, conn.user?.id, conn.user?.lid].map(normal)
    const mentioned = m.mentionedJid || m.msg?.contextInfo?.mentionedJid || []
    const quotedSender = normal(m.quoted?.sender || m.quoted?.participant)
    if (!mentioned.some(id => botIds.includes(normal(id))) && !m.quoted?.fromMe && !botIds.includes(quotedSender) && !/\bchiaki\b/i.test(text)) return true
  }
  prune(seen, 15 * 60000)
  prune(cooldowns, 10 * 60000)
  prune(histories, 20 * 60000)
  const messageId = `${m.chat}:${m.key?.id || m.id || ''}`
  if ((m.key?.id || m.id) && seen.has(messageId)) return true
  const key = `${m.chat}:${normal(m.sender || m.key?.participant || m.chat)}`
  if (active.has(key) || Date.now() - (cooldowns.get(key) || 0) < cfg.cooldownMs) return true
  const maxConcurrent = Number(cfg.maxConcurrent || 3)
  if (active.size >= maxConcurrent) return true
  if (m.key?.id || m.id) seen.set(messageId, Date.now())
  cooldowns.set(key, Date.now())
  active.add(key)
  let status
  try {
    status = await makeStatus(conn, m)
    await Promise.resolve(conn.sendPresenceUpdate?.('composing', m.chat)).catch(() => {})
    const intent = groupIntent(text)
    if (intent && (!media || /\b(grupo|participantes|miembros|admins|administradores)\b/.test(fold(text)))) {
      await groupAction(conn, m, intent, cfg, status)
      return true
    }
    if (wantsMusic(text) && (!media || media.type === 'audio')) {
      await sendMusic(conn, m, text, status)
      return true
    }
    if (wantsImage(text) && !media) {
      await sendGeneratedImage(conn, m, text, status)
      return true
    }
    if (wantsImage(text) && media && media.type !== 'audio') throw new Error('Zoner solo genera imágenes desde texto en este plugin; no puede editar fielmente la imagen adjunta. Envía la petición sin responder a una imagen.')
    let context = ''
    let images = []
    if (media) {
      await status.update('📥 Descargando el adjunto. Esperando…')
      const file = await downloadMedia(media, limits().mediaBytes, conn)
      if (/\b(bak|backup|copia de seguridad)\b/.test(fold(text)) && /\b(crea|creame|haz|hazme|guarda|genera|generame|pasame|envia|enviame|copia)\b/.test(fold(text))) {
        if (file.buffer.length > limits().artifactBytes) throw new Error('La copia BAK supera el límite de envío configurado.')
        const name = safeFilename(`${file.filename}.bak`)
        await send(conn, m, { document: file.buffer, fileName: name, mimetype: 'application/octet-stream', caption: 'Copia BAK exacta, sin modificar los bytes del archivo original.' })
        await status.finish('✅ Copia de seguridad enviada. Se conserva el archivo original byte por byte.')
        return true
      }
      if (['image', 'sticker'].includes(file.type)) {
        images = [await normalizeImage(file.buffer)]
        context = 'Imagen adjunta normalizada a JPEG. En stickers animados solo se analiza el primer fotograma.'
      } else if (['video', 'audio'].includes(file.type)) {
        const result = await analyzeAV(file.buffer, file.type, text, value => status.update(value))
        context = result.context
        images = result.images
        if (!text && file.type === 'audio' && result.transcript) {
          text = result.transcript.trim()
          if (wantsMusic(text)) { await sendMusic(conn, m, text, status); return true }
          if (wantsImage(text)) { await sendGeneratedImage(conn, m, text, status); return true }
        }
      } else context = await prepareDocument(file.buffer, file.filename, file.mime, text || 'Analiza este archivo.', value => status.update(value))
    }
    await status.update('🧠 Preparando la respuesta. Esperando…')
    await answer({ conn, m, prompt: text || 'Analiza este adjunto y describe lo relevante.', images, context, historyKey: key, status })
  } catch (error) {
    console.error('[Chiaki AI]', String(error.message || error).slice(0, 500))
    const message = `⚠️ ${String(error.message || 'No se pudo completar la solicitud.').slice(0, 700)}`
    if (status) await status.finish(message).catch(() => {})
    else await send(conn, m, { text: message }).catch(() => {})
  } finally {
    active.delete(key)
    await Promise.resolve(conn.sendPresenceUpdate?.('paused', m.chat)).catch(() => {})
  }
  return true
}

async function (m, { conn }) {
