async function (m, { conn, usedPrefix = '.' }) {
  if (m.isBaileys || !m.message) return false

  const msg = m.message
  let selectedId = null

  if (msg.interactiveResponseMessage) {
    try {
      const params = JSON.parse(msg.interactiveResponseMessage.nativeFlowResponseMessage?.paramsJson || '{}')
      selectedId = params.id
    } catch {}
  } else if (msg.listResponseMessage) {
    selectedId = msg.listResponseMessage.singleSelectReply?.selectedRowId
  }

  if (typeof selectedId !== 'string' || !selectedId.startsWith('gf:')) return false

  const [kind, ...parts] = selectedId.slice(3).split('|')
  let page = 1
  let relPath

  if (kind === 'd') {
    page = Math.max(1, parseInt(parts[0], 10) || 1)
    relPath = parts.slice(1).join('|')
  } else {
    relPath = parts.join('|')
  }

  const absPath = path.resolve(ROOT, relPath || '.')
  if (!withinRoot(absPath) || !fs.existsSync(absPath)) {
    await conn.reply(m.chat, `❎ ${small('ruta invalida')}.`, m)
    return true
  }

  try {
    if (kind === 'z') await sendZip(m, conn, absPath)
    else if (kind === 'f') await sendFile(m, conn, absPath)
    else if (kind === 'd') await showFolder(m, conn, absPath, { usedPrefix, command: 'getfile', page, menu: true })
    else return false
  } catch (e) {
    await conn.reply(m.chat, `❎ Error: ${e?.message || e}`, m)
  }
  return true
}
